def apply_official_rules() -> None:
    """Write RULES_2027 onto every matching top-level event row. Runs on
    every startup; idempotent. Only touches the rules fields (description,
    assessment_type, overview_*), never resources, chapters, or a coach's
    sub-topics."""
    db = SessionLocal()
    try:
        for name, rules in RULES_2027.items():
            topic = (
                db.query(models.Topic)
                .filter(models.Topic.name == name, models.Topic.parent_topic_id.is_(None))
                .first()
            )
            if topic is None:
                continue
            topic.description = rules["description"]
            topic.assessment_type = rules["assessment_type"]
            topic.overview_what = rules["what"]
            topic.overview_learn = rules["learn"]
            topic.overview_assessed = rules["assessed"]
            topic.overview_theme_2027 = rules["theme_2027"]
            topic.overview_notes = rules["notes"]
        db.commit()
    finally:
        db.close()
